    coeffs[392] = -d[17]*d[22] + d[16]*d[23] - d[5]*d[52] + d[4]*d[53];
    coeffs[393] = d[23]*d[28] - d[22]*d[29] - d[11]*d[46] + d[10]*d[47] - d[5]*d[76] + d[4]*d[77];
    coeffs[394] = d[23]*d[34] - d[22]*d[35] - d[17]*d[46] + d[16]*d[47] - d[11]*d[52] + d[10]*d[53] - d[5]*d[82] + d[4]*d[83];
    coeffs[395] = d[23]*d[40] - d[22]*d[41] - d[17]*d[52] + d[16]*d[53] - d[5]*d[88] + d[4]*d[89];
    coeffs[396] = -d[29]*d[46] + d[28]*d[47] + d[23]*d[58] - d[22]*d[59] - d[11]*d[76] + d[10]*d[77];
    coeffs[397] = -d[35]*d[46] + d[34]*d[47] - d[29]*d[52] + d[28]*d[53] + d[23]*d[64] - d[22]*d[65] - d[17]*d[76] + d[16]*d[77] - d[11]*d[82] + d[10]*d[83] - d[5]*d[106] + d[4]*d[107];
    coeffs[398] = -d[41]*d[46] + d[40]*d[47] - d[35]*d[52] + d[34]*d[53] + d[23]*d[70] - d[22]*d[71] - d[17]*d[82] + d[16]*d[83] - d[11]*d[88] + d[10]*d[89] - d[5]*d[112] + d[4]*d[113];
    coeffs[399] = -d[41]*d[52] + d[40]*d[53] - d[17]*d[88] + d[16]*d[89];
    coeffs[400] = d[47]*d[58] - d[46]*d[59] - d[29]*d[76] + d[28]*d[77];
    coeffs[401] = d[53]*d[58] - d[52]*d[59] + d[47]*d[64] - d[46]*d[65] - d[35]*d[76] + d[34]*d[77] - d[29]*d[82] + d[28]*d[83] + d[23]*d[94] - d[22]*d[95] - d[11]*d[106] + d[10]*d[107];
    coeffs[402] = d[53]*d[64] - d[52]*d[65] + d[47]*d[70] - d[46]*d[71] - d[41]*d[76] + d[40]*d[77] - d[35]*d[82] + d[34]*d[83] - d[29]*d[88] + d[28]*d[89] + d[23]*d[100] - d[22]*d[101] - d[17]*d[106] + d[16]*d[107] - d[11]*d[112] + d[10]*d[113] - d[5]*d[124] + d[4]*d[125];
    coeffs[403] = d[53]*d[70] - d[52]*d[71] - d[41]*d[82] + d[40]*d[83] - d[35]*d[88] + d[34]*d[89] - d[17]*d[112] + d[16]*d[113];
    coeffs[404] = -d[41]*d[88] + d[40]*d[89];
    coeffs[405] = -d[59]*d[76] + d[58]*d[77];
