    std::pow(r,2)*std::pow(k,3)*d[1] + std::pow(r,2)*std::pow(k,2)*d[7] + r*std::pow(k,3)*d[13] + std::pow(r,2)*k*d[25] + r*std::pow(k,2)*d[31] + std::pow(k,3)*d[37] + std::pow(r,2)*d[55] + r*k*d[61] + std::pow(k,2)*d[67] + r*d[91] + k*d[97] + d[115],std::pow(r,2)*std::pow(k,2)*d[19] + std::pow(r,2)*k*d[43] + r*std::pow(k,2)*d[49] + std::pow(r,2)*d[73] + r*k*d[79] + std::pow(k,2)*d[85] + r*d[103] + k*d[109] + d[121],
    std::pow(r,2)*std::pow(k,3)*d[2] + std::pow(r,2)*std::pow(k,2)*d[8] + r*std::pow(k,3)*d[14] + std::pow(r,2)*k*d[26] + r*std::pow(k,2)*d[32] + std::pow(k,3)*d[38] + std::pow(r,2)*d[56] + r*k*d[62] + std::pow(k,2)*d[68] + r*d[92] + k*d[98] + d[116],std::pow(r,2)*std::pow(k,2)*d[20] + std::pow(r,2)*k*d[44] + r*std::pow(k,2)*d[50] + std::pow(r,2)*d[74] + r*k*d[80] + std::pow(k,2)*d[86] + r*d[104] + k*d[110] + d[122],
    std::pow(r,2)*std::pow(k,3)*d[3] + std::pow(r,2)*std::pow(k,2)*d[9] + r*std::pow(k,3)*d[15] + std::pow(r,2)*k*d[27] + r*std::pow(k,2)*d[33] + std::pow(k,3)*d[39] + std::pow(r,2)*d[57] + r*k*d[63] + std::pow(k,2)*d[69] + r*d[93] + k*d[99] + d[117],std::pow(r,2)*std::pow(k,2)*d[21] + std::pow(r,2)*k*d[45] + r*std::pow(k,2)*d[51] + std::pow(r,2)*d[75] + r*k*d[81] + std::pow(k,2)*d[87] + r*d[105] + k*d[111] + d[123],
    std::pow(r,2)*std::pow(k,3)*d[4] + std::pow(r,2)*std::pow(k,2)*d[10] + r*std::pow(k,3)*d[16] + std::pow(r,2)*k*d[28] + r*std::pow(k,2)*d[34] + std::pow(k,3)*d[40] + std::pow(r,2)*d[58] + r*k*d[64] + std::pow(k,2)*d[70] + r*d[94] + k*d[100] + d[118],std::pow(r,2)*std::pow(k,2)*d[22] + std::pow(r,2)*k*d[46] + r*std::pow(k,2)*d[52] + std::pow(r,2)*d[76] + r*k*d[82] + std::pow(k,2)*d[88] + r*d[106] + k*d[112] + d[124],
    std::pow(r,2)*std::pow(k,3)*d[5] + std::pow(r,2)*std::pow(k,2)*d[11] + r*std::pow(k,3)*d[17] + std::pow(r,2)*k*d[29] + r*std::pow(k,2)*d[35] + std::pow(k,3)*d[41] + std::pow(r,2)*d[59] + r*k*d[65] + std::pow(k,2)*d[71] + r*d[95] + k*d[101] + d[119],std::pow(r,2)*std::pow(k,2)*d[23] + std::pow(r,2)*k*d[47] + r*std::pow(k,2)*d[53] + std::pow(r,2)*d[77] + r*k*d[83] + std::pow(k,2)*d[89] + r*d[107] + k*d[113] + d[125];
