static inline Eigen::Matrix<double, 6, 4> get_Mt(double *d, double r, double k, double f)
{
    Eigen::Matrix<double, 6, 4> M;
    M << k*d[7] - 1,0,d[9],std::pow(r,2)*k*f*d[0] + std::pow(r,2)*f*d[1] + std::pow(r,2)*d[2] + r*k*f*d[3] + r*f*d[4] + r*d[5] + k*f*d[6] + f*d[8] + d[10],0,k*d[7] - 1,d[17],std::pow(r,2)*k*f*d[11] + std::pow(r,2)*f*d[12] + std::pow(r,2)*d[13] + r*d[14] + k*f*d[15] + f*d[16] + d[18],k*d[26] - 1,0,d[28],std::pow(r,2)*k*f*d[19] + std::pow(r,2)*f*d[20] + std::pow(r,2)*d[21] + r*k*f*d[22] + r*f*d[23] + r*d[24] + k*f*d[25] + f*d[27] + d[29],0,k*d[26] - 1,d[36],std::pow(r,2)*k*f*d[30] + std::pow(r,2)*f*d[31] + std::pow(r,2)*d[32] + r*d[33] + k*f*d[34] + f*d[35] + d[37],k*d[45] - 1,0,d[47],std::pow(r,2)*k*f*d[38] + std::pow(r,2)*f*d[39] + std::pow(r,2)*d[40] + r*k*f*d[41] + r*f*d[42] + r*d[43] + k*f*d[44] + f*d[46] + d[48],0,
    k*d[45] - 1,
    d[55],
    std::pow(r,2)*k*f*d[49] + std::pow(r,2)*f*d[50] + std::pow(r,2)*d[51] + r*d[52] + k*f*d[53] + f*d[54] + d[56];
    return M;
}

std::tuple<std::vector<Eigen::Matrix3d>, std::vector<Eigen::Vector3d>, std::vector<double>, std::vector<double>>
solver_up3pfr(const Eigen::Matrix<double, 2, 3> &p_query_orig, const Eigen::Matrix<double, 3, 3> &X, const Eigen::Matrix3d &Rxz)
{
   
    // Normalize data
    double s2 = (p_query_orig.col(0).squaredNorm() + p_query_orig.col(1).squaredNorm() + p_query_orig.col(2).squaredNorm()) / 36.0;
    double s = std::sqrt(s2);
    Eigen::Vector2d p_query1 = p_query_orig.col(0) / s;
    Eigen::Vector2d p_query2 = p_query_orig.col(1) / s;
    Eigen::Vector2d p_query3 = p_query_orig.col(2) / s;
    
    // Others
    Eigen::Vector2d p_ref1 = X.col(0).hnormalized();
    Eigen::Vector2d p_ref2 = X.col(1).hnormalized();
    Eigen::Vector2d p_ref3 = X.col(2).hnormalized();
    double d1 = X.col(0)(2);
    double d2 = X.col(1)(2);
    double d3 = X.col(2)(2);

    // TODO: Investigare references
    Eigen::Matrix3d I = Eigen::Matrix3d::Identity();
    Eigen::Vector3d O = Eigen::Vector3d::Zero();

    // Generate
    Eigen::Matrix<double, 19, 1> C1 = generate_coeffs_point_based(I, O, p_ref1, d1, p_query1, Rxz);
    Eigen::Matrix<double, 19, 1> C2 = generate_coeffs_point_based(I, O, p_ref2, d2, p_query2, Rxz);
    Eigen::Matrix<double, 19, 1> C3 = generate_coeffs_point_based(I, O, p_ref3, d3, p_query3, Rxz);
    Eigen::Matrix<double, 19 * 3, 1> C;
    C << C1, C2, C3;
    double* c = C.data();

    // Generate coeffs for next step
    Eigen::Matrix<double, 6, 21> M = generate_coeffs_Mmod(c);
    double* c2 = M.data();

    // Solve problem for 2 variables
    Eigen::MatrixXcd sols = solver_up3pfr(c2);
    
    //OUTPUT
    std::vector<Eigen::Matrix3d> Rs;
    std::vector<Eigen::Vector3d> ts;
    std::vector<double> fs;
    std::vector<double> ks;

	// Compute poses from solutions
	for (int i = 0; i < 14; ++i) {
		if (std::abs(sols(0, i).imag()) > SMALL_NUMBER)
			continue;

		double r = sols(0, i).real();
        double k = sols(1, i).real();

        // Extract focal length
        Eigen::Matrix<double, 6, 2> Mbar = get_M(c2, r, k);
        Eigen::FullPivHouseholderQR<Eigen::Matrix2d> qr(Mbar.transpose() * Mbar);
        Eigen::Matrix2d Q = qr.matrixQ();
        Eigen::Vector2d Nbar = Q.rightCols<1>();
        double f = Nbar(0) / Nbar(1);

        Eigen::Matrix<double, 6, 4> Mbar2 = get_Mt(c, r, k, f);
        Eigen::FullPivHouseholderQR<Eigen::Matrix4d> qr2(Mbar2.transpose() * Mbar2);
        Eigen::Matrix4d Q2 = qr2.matrixQ();
        Eigen::Vector4d Nbar2 = Q2.rightCols<1>();
        Eigen::Vector3d t = Nbar2.head(3) / Nbar2(3);
        
        // Fix scale and normalization
        k /= s2;
        f *= s;
        t /= 1 + r * r;
        t(0) *= s / f;
        t(1) *= s / f;

        // Return full rotation
        double w = 1 + r * r;
        double c = (1 - r * r) / w;
        double s = 2 * r / w;
        Eigen::Matrix3d R;
        R << c, 0, -s, 0, 1, 0, s, 0, c;

		Rs.push_back(R * Rxz);
		ts.push_back(t);
		fs.push_back(f);
		// k -> k * f^2, due to a convention in radialpose, where the order of focal length
		// differs from the original implementation. It makes it comparable to other methods.
		ks.push_back(k * f * f);
	}
	
	return std::make_tuple(Rs, ts, fs, ks);
}
